"""Explicit seam transitions; no width averaging during source normalization."""


def read(settings, canonical, sections, connectors, bundles):
    from .model import ContractError, TransitionRecord, _finite
    streets = {s.id: s for s in canonical.streets}
    attached = {m for c in connectors.values() for m in c.members}
    result, used = {}, set()
    for r in settings.transitions:
        if r.transition_id in result:
            raise ContractError('Duplicate transition ID')
        street = streets.get(r.street_id)
        pair = (r.before_section, r.after_section)
        adjacent = [] if street is None else [(a, b) for a, b in zip(street.sections, street.sections[1:])
                                               if (a[0], b[0]) == pair]
        if len(adjacent) != 1 or pair in used:
            raise ContractError('A transition must identify one unique ordered Section seam')
        (a, af), (b, bf) = adjacent[0]
        for sid, end in ((a, 1 if af else 0), (b, 0 if bf else 1)):
            record = sections[sid]
            if (sid, end) in attached or (record.clip_end if end else record.clip_start) > 0.:
                raise ContractError('A transition cannot occupy an attached or excluded Section seam')
        if sections[a].preset != sections[b].preset or abs(sections[a].rise-sections[b].rise) > 1e-7:
            raise ContractError('A width transition must preserve the same profile and rise')
        half = _finite(r.minimum_half_length, 'Transition minimum half length', positive=True)
        slope = _finite(r.maximum_edge_slope, 'Transition maximum edge slope', positive=True)
        if slope > 1.:
            raise ContractError('Transition edge slope must not exceed one')
        result[r.transition_id] = TransitionRecord(r.transition_id, r.street_id, a, b, half, slope)
        used.add(pair)
    return result


def endpoints(net):
    """Stable endpoint identities; GN calculates extents from the live widths."""
    result = {}
    streets = {s.id: s for s in net.canonical.streets}
    for record in net.transition_records.values():
        items = dict(streets[record.street_id].sections)
        result[(record.before_section, 1 if items[record.before_section] else 0)] = record
        result[(record.after_section, 0 if items[record.after_section] else 1)] = record
    return result
